example_solution:
#[derive(Drop)]
pub enum LogLevel {
    Info,
    Warning,
    Error,
    Debug,
}

pub fn log(level: LogLevel, message: ByteArray) -> ByteArray {
    match level {
        LogLevel::Info => info(message),
        LogLevel::Warning => warn(message),
        LogLevel::Error => error(message),
        LogLevel::Debug => format!("[DEBUG]: {message}"),
    }
}

pub fn info(message: ByteArray) -> ByteArray {
    format!("[INFO]: {message}")
}

pub fn warn(message: ByteArray) -> ByteArray {
    format!("[WARNING]: {message}")
}

pub fn error(message: ByteArray) -> ByteArray {
    format!("[ERROR]: {message}")
}

test_code:
use semi_structured_logs::{LogLevel, error, info, log, warn};

#[test]
fn emits_info() {
    assert_eq!(info("Timezone changed"), "[INFO]: Timezone changed");
}

#[test]
#[ignore]
fn emits_warning() {
    assert_eq!(warn("Timezone not set"), "[WARNING]: Timezone not set");
}

#[test]
#[ignore]
fn emits_error() {
    assert_eq!(error("Disk full"), "[ERROR]: Disk full");
}

#[test]
#[ignore]
fn log_emits_info() {
    assert_eq!(log(LogLevel::Info, "Timezone changed"), "[INFO]: Timezone changed");
}

#[test]
#[ignore]
fn log_emits_warning() {
    assert_eq!(log(LogLevel::Warning, "Timezone not set"), "[WARNING]: Timezone not set");
}

#[test]
#[ignore]
fn log_emits_error() {
    assert_eq!(log(LogLevel::Error, "Disk full"), "[ERROR]: Disk full");
}

#[test]
#[ignore]
fn add_a_variant() {
    assert_eq!(log(LogLevel::Debug, "reached line 123"), "[DEBUG]: reached line 123");
}
